/**
 * Purges old FB_Integration_Log__c records.
 * - Non-ERROR logs (including blank Level__c) are deleted once older than 30 days.
 * - ERROR logs are deleted once older than 180 days.
 */
public without sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    public static final String JOB_NAME = 'Log purge (nightly)';
    public static final String CRON_NIGHTLY = '0 0 2 * * ?';
    private static final Integer DEFAULT_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final Integer SYNC_LIMIT = 9000;
    private static final Integer BATCH_SIZE = 2000;

    public LogPurgeJob() {
    }

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_NIGHTLY, new LogPurgeJob());
    }

    private static Datetime defaultCutoff() {
        return Datetime.now().addDays(-DEFAULT_RETENTION_DAYS);
    }

    private static Datetime errorCutoff() {
        return Datetime.now().addDays(-ERROR_RETENTION_DAYS);
    }

    // Schedulable: purge synchronously; hand off any remainder to a batch run.
    public void execute(SchedulableContext sc) {
        Datetime dCut = defaultCutoff();
        Datetime eCut = errorCutoff();
        List<FB_Integration_Log__c> toDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :dCut
              AND (Level__c != 'ERROR' OR Level__c = null OR CreatedDate < :eCut)
            LIMIT :(SYNC_LIMIT + 1)
        ];
        Boolean more = toDelete.size() > SYNC_LIMIT;
        if (more) {
            toDelete.remove(toDelete.size() - 1);
        }
        if (!toDelete.isEmpty()) {
            Database.delete(toDelete, false);
        }
        if (more) {
            Database.executeBatch(new LogPurgeJob(), BATCH_SIZE);
        }
    }

    // Batchable (used only for large backlogs)
    public Database.QueryLocator start(Database.BatchableContext bc) {
        Datetime dCut = defaultCutoff();
        Datetime eCut = errorCutoff();
        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :dCut
              AND (Level__c != 'ERROR' OR Level__c = null OR CreatedDate < :eCut)
        ]);
    }

    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }
        Database.delete(scope, false);
    }

    public void finish(Database.BatchableContext bc) {
    }
}
```

**Retention rules**
- Logs older than 30 days are deleted unless `Level__c` is `ERROR`.
- Logs with a blank `Level__c` follow the 30-day rule. The query also checks `Level__c = null` explicitly so blanks are always included.
- `ERROR` logs are deleted only once they are older than 180 days.
- SOQL comparison ignores case, so a level stored as `error` is also kept for 180 days.

**Delete behaviour**
- Each run first deletes up to 9,000 matching records synchronously.
- If more remain, it starts a batch run of the same class for the rest, in batches of 2,000.
- Deletes allow partial success, so one locked record does not stop the purge.

**Schedule:** `scheduleNightly()` schedules the job with cron `0 0 2 * * ?` (daily at 02:00) under the name `Log purge (nightly)`. It returns the scheduled job Id.

