/**
 * Sends website gifts through the NPSP Data Importer (BDI) so that NPSP's contact
 * matching, household creation and donation processing rules apply. Each staged
 * npsp__DataImport__c record stays in the org as the audit trail of the import.
 */
public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    private static final String STATUS_IMPORTED = 'Imported';

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1. Stage one Data Import record per gift, in input order.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift g : gifts) {
            WebGift gift = (g == null) ? new WebGift() : g;
            staged.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift.firstName,
                npsp__Contact1_Lastname__c       = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c         = gift.amount,
                npsp__Donation_Date__c           = gift.giftDate,
                npsp__Donation_Donor__c          = 'Contact1'
            ));
        }
        insert staged;

        // 2. Process synchronously with NPSP's Data Import API and the org's Data Import settings.
        //    getInstance() returns the hierarchy value, or a record with the field defaults
        //    when none has been saved.
        npsp__Data_Import_Settings__c diSettings = npsp__Data_Import_Settings__c.getInstance();
        if (diSettings == null) {
            diSettings = new npsp__Data_Import_Settings__c();
        }
        npsp.BDI_DataImport_API.processDataImportRecords(diSettings, staged, false);

        // 3. Re-query the processed records to read NPSP's results.
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>([
            SELECT Id, npsp__Status__c, npsp__Contact1Imported__c,
                   npsp__DonationImported__c, npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :staged
        ]);

        // 4. Build the results in input order.
        for (npsp__DataImport__c di : staged) {
            npsp__DataImport__c row = processed.get(di.Id);
            ImportResult r = new ImportResult();
            if (row == null) {
                r.success = false;
                r.errorMessage = 'Data Import record could not be found after processing.';
            } else {
                r.success = (row.npsp__Status__c == STATUS_IMPORTED);
                r.contactId = row.npsp__Contact1Imported__c;
                r.opportunityId = row.npsp__DonationImported__c;
                if (!r.success) {
                    r.errorMessage = String.isNotBlank(row.npsp__FailureInformation__c)
                        ? row.npsp__FailureInformation__c
                        : 'Import did not complete. Status: ' + row.npsp__Status__c;
                }
            }
            results.add(r);
        }
        return results;
    }
}
